"use client";

import { ImagePlus, RotateCcw, Save, Smartphone, StretchHorizontal } from "lucide-react";
import Image from "next/image";
import { useRouter } from "next/navigation";
import { type ChangeEvent, useCallback, useRef, useState, useTransition } from "react";
import Cropper, { type Area } from "react-easy-crop";
import { toast } from "sonner";

import { mutateJson } from "@/lib/client/mutate";
import { postAdminSection, type SectionEnvelope } from "@/features/admin/admin-section-kit";
import { formatDuration, formatPrice } from "@/lib/catalog";
import type { CatalogEntity } from "@/lib/types";

function clampZoom(value: number) {
  return Math.min(200, Math.max(100, Math.round(value)));
}

export function MediaCropEditor({ entity }: { entity: CatalogEntity }) {
  const router = useRouter();
  const [crop, setCrop] = useState({ x: 0, y: 0 });
  const [focal, setFocal] = useState({ x: entity.cover_offset_x, y: entity.cover_offset_y });
  const [fit, setFit] = useState<"cover" | "contain">(entity.cover_fit);
  const [zoomPercent, setZoomPercent] = useState(clampZoom(entity.image_zoom || 100));
  const cropInteraction = useRef(false);
  const [isPending, startTransition] = useTransition();
  const [uploading, setUploading] = useState(false);
  const source = entity.hero_file_path || "/brand/logo.png";
  const isShow = entity.entity_type === "show_program";
  const aspect = isShow ? 16 / 10 : 4 / 5;

  const onCropComplete = useCallback((croppedArea: Area) => {
    if (!cropInteraction.current) return;
    setFocal({
      x: Math.round(croppedArea.x + croppedArea.width / 2),
      y: Math.round(croppedArea.y + croppedArea.height / 2),
    });
  }, []);

  const setZoom = useCallback((value: number) => {
    setZoomPercent(clampZoom(value * 100));
  }, []);

  function reset() {
    cropInteraction.current = false;
    setCrop({ x: 0, y: 0 });
    setFocal({ x: 50, y: 50 });
    setFit("cover");
    setZoomPercent(100);
  }

  function save() {
    startTransition(async () => {
      try {
        await mutateJson(`/api/admin/entities/${entity.id}/crop`, {
          cover_offset_x: focal.x,
          cover_offset_y: focal.y,
          cover_fit: fit,
          image_zoom: zoomPercent,
        });
        toast.success("Кадрирование сохранено");
      } catch (error) {
        toast.error(error instanceof Error ? error.message : "Не удалось сохранить.");
      }
    });
  }

  async function upload(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    setUploading(true);
    try {
      const csrfResponse = await fetch("/api/csrf", { cache: "no-store", credentials: "same-origin" });
      if (!csrfResponse.ok) throw new Error("Не удалось подготовить защищённую загрузку.");
      const csrf = (await csrfResponse.json()) as { token: string };
      const body = new FormData();
      body.set("file", file);
      const uploadResponse = await fetch("/api/admin/media/upload", {
        method: "POST",
        credentials: "same-origin",
        headers: { "x-csrf-token": csrf.token },
        body,
      });
      const uploaded = (await uploadResponse.json()) as {
        authenticated?: boolean;
        success?: boolean;
        message?: string;
        media?: {
          original: { path: string; width: number; height: number; bytes: number; mimeType: string };
          variants: Array<{ path: string; width: number; height: number; bytes: number; format: "webp" | "avif" }>;
        };
      };
      if (uploadResponse.status === 401 || uploaded.authenticated === false) {
        window.location.assign("/admin/login");
        return;
      }
      if (!uploadResponse.ok || !uploaded.success || !uploaded.media) {
        throw new Error(uploaded.message || "Загрузка не выполнена.");
      }
      const preferred = uploaded.media.variants
        .filter((variant) => variant.format === "webp")
        .toSorted((left, right) => right.width - left.width)[0];
      const display = preferred ?? uploaded.media.original;
      const attached = await postAdminSection<SectionEnvelope & { media_id?: number }>("media", {
        action: "attach_generated",
        owner_id: entity.id,
        owner_type: entity.entity_type,
        file_path: display.path,
        original_path: uploaded.media.original.path,
        width: display.width,
        height: display.height,
        bytes: display.bytes,
        mime_type: "mimeType" in display ? display.mimeType : `image/${display.format}`,
        variants: uploaded.media.variants,
      });
      if (attached.success === false || !attached.media_id) {
        throw new Error(attached.message || "Файл обработан, но не привязан к карточке.");
      }
      const hero = await postAdminSection<SectionEnvelope>("media", {
        action: "set_hero",
        media_id: attached.media_id,
        owner_id: entity.id,
        owner_type: entity.entity_type,
      });
      if (hero.success === false) throw new Error(hero.message || "Не удалось назначить обложку.");
      toast.success("Фотография оптимизирована и назначена обложкой");
      router.refresh();
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Не удалось загрузить фотографию.");
    } finally {
      setUploading(false);
    }
  }

  return (
    <div className="media-editor-grid">
      <section className="admin-surface media-editor-main">
        <div className="admin-surface-head"><div><p className="eyebrow">ОБЛОЖКА</p><h2>Неразрушающее кадрирование</h2><p>Оригинал остаётся неизменным. Сохраняются focal point и режим вписывания.</p></div></div>
        <div className="cropper-stage">
          <Cropper image={source} crop={crop} zoom={zoomPercent / 100} minZoom={1} maxZoom={2} zoomSpeed={0.05} aspect={aspect} onCropChange={setCrop} onCropComplete={onCropComplete} onInteractionStart={() => { cropInteraction.current = true; }} onInteractionEnd={() => { cropInteraction.current = false; }} onZoomChange={setZoom} objectFit={fit === "contain" ? "contain" : "cover"} showGrid />
        </div>
        <div className="crop-controls">
          <label>Режим<select value={fit} onChange={(event) => setFit(event.target.value as "cover" | "contain")}><option value="cover">Заполнить рамку</option><option value="contain">Показать целиком</option></select></label>
          <label className="crop-zoom-control"><span>Приближение <output>{zoomPercent}%</output></span><input aria-label="Приближение" min="100" max="200" step="5" type="range" value={zoomPercent} onChange={(event) => setZoomPercent(clampZoom(Number(event.target.value)))} /></label>
          <button className="button button-secondary" onClick={reset} type="button"><RotateCcw size={17} /> Сбросить</button>
          <button className="button button-violet" disabled={isPending} onClick={save} type="button"><Save size={17} /> {isPending ? "Сохраняем…" : "Сохранить"}</button>
        </div>
        <div className="crop-meta"><span>Фокус X: <strong>{focal.x}%</strong></span><span>Фокус Y: <strong>{focal.y}%</strong></span><span>Масштаб: <strong>{zoomPercent}%</strong></span></div>
      </section>
      <aside className="media-preview-stack">
        <section className="admin-surface"><div className="admin-surface-head"><div><p className="eyebrow">LIVE PREVIEW</p><h2>Карточка на сайте</h2></div></div><div className={`crop-preview ${isShow ? "is-show" : ""}`}><div><Image src={source} alt="" fill sizes="420px" style={{ objectFit: fit, objectPosition: `${focal.x}% ${focal.y}%`, transform: `scale(${zoomPercent / 100})`, transformOrigin: `${focal.x}% ${focal.y}%` }} unoptimized /></div><h3>{entity.name}</h3><p>{isShow ? `${formatDuration(entity.default_duration_minutes)} · ${formatPrice(entity.base_price)}` : entity.short_description}</p></div></section>
        <section className="admin-surface"><div className="preview-tabs"><span><StretchHorizontal /> Desktop</span><span><Smartphone /> Mobile</span></div><div className="media-pipeline"><div><span>Оригинал</span><strong>Хранится без изменений</strong></div><div><span>WebP</span><strong>480 · 768 · 1280 · 1920</strong></div><div><span>AVIF</span><strong>Автоматически</strong></div><div><span>EXIF/GPS</span><strong>Удаляется из вариантов</strong></div></div><label className={`media-upload-button ${uploading ? "is-disabled" : ""}`}><ImagePlus /> {uploading ? "Обрабатываем…" : "Загрузить новую фотографию"}<input accept="image/avif,image/jpeg,image/png,image/webp" disabled={uploading} onChange={(event) => void upload(event)} type="file" /></label></section>
      </aside>
    </div>
  );
}
